2	 * furl-compatible URL splitter.
3	 *
4	 * Splits a URL string into {scheme, netloc, path, query, fragment}.
5	 * scheme is a lowercased string or null, netloc is a string or null,
6	 * path/query/fragment are strings (possibly empty).
7	 */
8	export function urlsplit(url) {
9	  // 1. Remove ALL tab, carriage return and newline characters.
10	  url = url.replace(/[\t\r\n]/g, '');
11	
12	  // 2. fragment = substring after the FIRST '#', url = before it.
13	  let fragment = '';
14	  const hashIdx = url.indexOf('#');
15	  if (hashIdx !== -1) {
16	    fragment = url.slice(hashIdx + 1);
17	    url = url.slice(0, hashIdx);
18	  }
19	
20	  // 3. query = substring after the FIRST '?', url = before it.
21	  let query = '';
22	  const qIdx = url.indexOf('?');
23	  if (qIdx !== -1) {
24	    query = url.slice(qIdx + 1);
25	    url = url.slice(0, qIdx);
26	  }
27	
28	  // 4. scheme: optional scheme part (if present and non-empty must start
29	  //    with an ASCII letter and contain no '/' or ':'), followed by ':'.
30	  //    An empty scheme before the colon is allowed.
31	  let scheme = null;
32	  let rest = url;
33	  const m = /^(?:([A-Za-z][^/:]*)?):(.*)$/s.exec(url);
34	  if (m !== null) {
35	    scheme = (m[1] || '').toLowerCase();
36	    rest = m[2];
37	  }
38	
39	  // 5. If rest starts with '//': netloc up to the next '/' (backslash
40	  //    does NOT terminate the netloc); otherwise netloc is null.
41	  let netloc = null;
42	  let path;
43	  if (rest.startsWith('//')) {
44	    const afterSlashes = rest.slice(2);
45	    const slashIdx = afterSlashes.indexOf('/');
46	    if (slashIdx === -1) {
47	      netloc = afterSlashes;
48	      path = '';
49	    } else {
50	      netloc = afterSlashes.slice(0, slashIdx);
51	      path = afterSlashes.slice(slashIdx);
52	    }
53	  } else {
54	    path = rest;
55	  }
56	
57	  return { scheme, netloc, path, query, fragment };
58	}

