// Differential test: /workspace/dataset/test2_executable vs node /output/test2.mjs
// Compares stdout and exit code. For exit-1 cases, also requires our stderr
// to be non-empty. Stderr text is NOT compared (Python traceback vs ours,
// and argparse prog-name differences are expected).
import { execFileSync } from 'node:child_process';

const REF = '/workspace/dataset/test2_executable';
const OURS = '/output/test2.mjs';

function runRef(argv) {
  try {
    const stdout = execFileSync(REF, argv, { encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'] });
    return { code: 0, stdout };
  } catch (e) {
    return { code: e.status ?? -1, stdout: e.stdout?.toString() ?? '' };
  }
}

function runOurs(argv) {
  try {
    const stdout = execFileSync('node', [OURS, ...argv], { encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'] });
    return { code: 0, stdout, stderr: '' };
  } catch (e) {
    return { code: e.status ?? -1, stdout: e.stdout?.toString() ?? '', stderr: e.stderr?.toString() ?? '' };
  }
}

